from pathlib import Path
import json, html
import cinematic
from project_extras import photomax_showcase, mellana_showcase

ROOT=Path(__file__).resolve().parent
OUT=ROOT/'dist';OUT.mkdir(exist_ok=True)
projects=json.loads((ROOT/'projects.json').read_text(encoding='utf-8'))
dimensions={i['name']:(i['width'],i['height']) for i in json.loads((ROOT/'asset-provenance.json').read_text())}
def esc(t):return html.escape(t,quote=True)
def arrow(cls=''):return f'<svg class="arrow {cls}" viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M5 19 19 5M5 5h14v14" stroke="currentColor" stroke-width="1.6"/></svg>'
def star():return '<svg class="star" viewBox="0 0 100 100" aria-hidden="true"><g stroke="currentColor" stroke-width="9"><path d="M50 4v92M4 50h92M17.5 17.5l65 65m0-65-65 65"/></g></svg>'
def img(name,alt,cls='',eager=False):
    w,h=dimensions[name]
    return f'<img src="/assets/{name}.webp" alt="{esc(alt)}" width="{w}" height="{h}" class="{cls}" loading="{"eager" if eager else "lazy"}" decoding="async"{(" fetchpriority=\"high\"" if eager else "")}>'
def nav(page):
    return f'''<a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="nav-wrap"><a href="/" class="wordmark" aria-label="Karthik Vempati home">karthik<span class="brand-dot">.</span></a><button class="menu-button" aria-expanded="false" aria-controls="primary-nav">Menu <span>＋</span></button><nav id="primary-nav" aria-label="Main navigation"><a href="/#collection" {('aria-current="page"' if page=='work' else '')}>Work</a><a href="/#toolkit">Toolkit</a><a href="/about/" {('aria-current="page"' if page=='about' else '')}>About</a><a href="/resume/" {('aria-current="page"' if page=='resume' else '')}>Résumé</a><a href="/#contact" class="nav-contact">Let’s talk {arrow()}</a></nav></div><div class="reading-progress" aria-hidden="true"></div></header>'''
def footer():
    return f'''<footer id="footer"><div class="container footer-top"><div class="footer-brand"><img class="footer-portrait" src="/assets/karthik-footer-portrait.png" alt="Karthik smiling, framed by a red circular graphic" width="866" height="790" loading="lazy" decoding="async"><a href="/" class="wordmark" aria-label="Karthik Vempati home">karthik<span class="brand-dot">.</span></a></div><p>Thoughtful interfaces. Distinctive identities.</p><a class="text-link" href="#top">Back to top <span aria-hidden="true">↑</span></a></div><div class="container footer-bottom"><span>© 2026 Karthik Vempati <span class="portfolio-version">Version 1</span></span><span>San Francisco, California</span><a href="https://www.linkedin.com/in/karthikvempati-design" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a></div></footer>'''
def contact():
    return cinematic.contact(arrow)
def shell(title,description,content,page='home'):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · Karthik Vempati · Version 1</title><meta name="portfolio-version" content="1.0.0"><meta name="description" content="{esc(description)}"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#18201c"><link rel="icon" href="/favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="/site.css"><link rel="stylesheet" href="/cinematic.css"><link rel="stylesheet" href="/inner-pages.css"><link rel="stylesheet" href="/project-galleries.css"><link rel="stylesheet" href="/review-additions.css"><script src="/site.js" defer></script><script src="/motion.js" defer></script><script src="/echo.js" defer></script></head><body id="top" data-page="{page}">{nav(page)}<main id="main">{content}</main>{footer()}<button class="global-motion" aria-pressed="false" title="Pause decorative motion">Motion on <span aria-hidden="true">Ⅱ</span></button><dialog class="lightbox" aria-labelledby="lightbox-caption"><div class="lightbox-top"><span>Project detail</span><div><a class="full-size" target="_blank" rel="noopener" href="/">Open image ↗</a><button class="close-lightbox" aria-label="Close image">✕</button></div></div><div class="lightbox-body"><img alt="" class="lightbox-image"></div><div class="lightbox-bottom"><button class="previous-image" aria-label="Previous image">←</button><p id="lightbox-caption"></p><button class="next-image" aria-label="Next image">→</button></div></dialog></body></html>'''
def write(path,text):
    dest=OUT/path;dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(text,encoding='utf-8')
def project_card(p,i):
    return f'''<article class="project-card reveal" data-categories="{p['filters']}"><a href="/work/{p['slug']}/" aria-label="Explore {esc(p['name'])}: {esc(p['tagline'])}"><div class="project-art {p['slug']}">{img(p['cover'],p['coverAlt'])}<span class="project-open">{arrow()}</span><span class="project-number">0{i+1}</span></div><div class="project-info"><div><h3>{p['name']}</h3><p>{p['tagline']}</p></div><span class="project-discipline">{p['category']}</span></div></a></article>'''

home=cinematic.home(projects,img,arrow,project_card)
write(Path('index.html'),shell('UI/UX & Visual Designer','Karthik Vempati is a San Francisco-based UI/UX designer with graphic-design strengths. Explore digital experiences, brand identities, and design case studies.',home))

for index,p in enumerate(projects):
    gallery=[]
    for name,caption,size in p['gallery']:
        gallery.append(f'<figure class="gallery-item {size} reveal"><button class="zoom-image" data-full="/assets/{name}.webp" data-caption="{esc(caption)}" aria-label="Enlarge image: {esc(caption)}">{img(name,caption)}<span class="zoom-hint" aria-hidden="true">↗</span></button><figcaption>{caption}</figcaption></figure>')
    video=''
    if p.get('video'):
        video=f'<figure class="video-figure reveal"><video controls playsinline preload="none" poster="/assets/{p["poster"]}.webp" aria-label="{esc(p["name"])} design walkthrough"><source src="/assets/{p["video"]}.mp4" type="video/mp4"><a href="/assets/{p["video"]}.mp4">Open the walkthrough video</a></video><figcaption>{p["videoCaption"]} <span>Silent walkthrough · playback controls available</span></figcaption></figure>'
    banner=''
    if p['slug']=='photomax':
        banner=photomax_showcase(img)
    elif p['slug']=='mellana':
        banner=mellana_showcase(img)
    nxt=projects[(index+1)%len(projects)]
    content=f'''<div class="container case-intro {p['slug']}"><a class="back-link" href="/#collection">← All work</a><p class="section-label">{p['eyebrow']}</p><h1>{p['name']}<span class="case-dot" style="background:{p['color']}"></span></h1><p class="case-tagline">{p['tagline']}</p><div class="case-summary"><p>{p['summary']}</p><dl><div><dt>Format</dt><dd>{p['format']}</dd></div><div><dt>Focus</dt><dd>{p['focus']}</dd></div></dl></div></div><figure class="container case-cover">{img(p['cover'],p['coverAlt'],eager=True)}</figure><nav class="case-nav" aria-label="Case study sections"><div class="container"><a href="#overview">01 Overview</a><a href="#decisions">02 Decisions</a><a href="#design">03 Design</a><a href="#reflection">04 Reflection</a></div></nav><div class="container"><section class="case-section overview" id="overview"><p class="section-label">01 / The context</p><div><h2>{'A useful starting point.' if p['slug']=='prebook' else 'The experience behind the screens.'}</h2><p class="large-copy">{p['overview']}</p><div class="challenge"><h3>The design challenge</h3><p>{p['challenge']}</p></div></div></section><section class="case-section decisions" id="decisions"><p class="section-label">02 / Design decisions</p><div><h2>What shaped<br><em>the experience.</em></h2><div class="decision-list">{''.join(f'<article class="reveal"><span>0{i+1}</span><div><h3>{d[0]}</h3><p>{d[1]}</p></div></article>' for i,d in enumerate(p['decisions']))}</div></div></section><section class="design-section" id="design"><div class="section-title"><div><p class="section-label">03 / The design</p><h2>From thinking<br><em>to making.</em></h2></div><p>Explore the original design work.<br>Select an image for a closer look.</p></div>{video}<div class="case-gallery">{''.join(gallery)}</div>{banner}</section><section class="case-section reflection" id="reflection"><p class="section-label">04 / Reflection</p><div><h2>What this<br><em>work brings together.</em></h2><p class="large-copy">{p['reflection']}</p><div class="tags">{''.join(f'<span>{s}</span>' for s in p['skills'])}</div>{f'<p class="credit">{p["credit"]}</p>' if p.get('credit') else ''}</div></section></div><a class="next-project" href="/work/{nxt['slug']}/"><div class="container"><div><span class="section-label">Keep exploring / Next project</span><h2>{nxt['name']}</h2></div>{arrow()}</div></a>'''
    write(Path('work')/p['slug']/'index.html',shell(p['name'],p['summary'],content,'work'))

experience=[
('July 2024 — Present','AbbVie','User Experience Designer','South San Francisco, CA','Healthcare digital products, user-centered design, reusable design systems, stakeholder collaboration, and UX/UI team mentorship.'),
('January 2022 — July 2024','Cotiviti','UI/UX Designer','South Jordan, UT','Healthcare payment accuracy and analytics tools. User flows, interactive prototypes, usability feedback, and reusable Figma components.'),
('June — December 2021','Rogue Innovation + Design','UI/UX Designer Intern','Concord, CA','Research support, high-fidelity mockups, interactive prototypes, and contributions to UI components and design guidelines.'),
('October 2016 — December 2018','Way to Webs','UI/UX Designer','Hyderabad, India','Responsive websites and e-commerce interfaces, user journeys, navigation, interactive prototypes, and design assets.'),
('September 2015 — September 2016','SABOO RKS Motors','Graphic Designer','Hyderabad, India','Print and digital campaigns, showroom graphics, signage, and production-ready artwork for an automotive business.')]
experience_html=''.join(f'<article class="experience-row reveal"><p class="experience-date">{date}</p><div><h3>{name}</h3><p class="role-name">{role} <span>· {location}</span></p><p>{body}</p></div></article>' for date,name,role,location,body in experience)
about=f'''<section class="about-hero container"><p class="section-label">The person behind the work</p><h1>Hi, I’m Karthik.<br><em>Designer, by nature.</em></h1><div class="about-layout"><figure class="about-photo">{img('karthik','Karthik smiling outdoors against a snowy mountain landscape',eager=True)}<figcaption>Based in San Francisco, California.</figcaption></figure><div class="about-story"><h2>Curiosity connects<br>the dots.</h2><p class="large-copy">I’m a UI/UX and graphic designer with 8+ years of experience across healthcare, web and e-commerce, and automotive design.</p><p>My background in applied arts and computer graphics shaped how I think about design: structure and expression belong together. I enjoy turning a complex workflow into something people can understand, while giving it a visual identity that feels considered.</p><p>My work spans research, user journeys, wireframes, prototypes, interface systems, brand identity, and print. I collaborate with product managers, engineers, and stakeholders to connect design choices with the task at hand.</p><a class="button dark" href="/resume/">View my résumé {arrow()}</a></div></div></section><section class="experience-section container"><div class="section-title"><div><p class="section-label">Experience</p><h2>A practice built<br><em>across disciplines.</em></h2></div><p>From visual communication<br>to complex digital products.</p></div><div class="experience-list">{experience_html}</div></section><section class="education-section"><div class="container education-grid"><div><p class="section-label">Education</p><h2>Art as a foundation.<br><em>Design as a practice.</em></h2></div><div><article><span>2019–2021</span><h3>MA in Computer Graphics</h3><p>Academy of Art University · San Francisco</p></article><article><span>2010–2015</span><h3>BFA in Applied Arts</h3><p>Osmania University · Hyderabad</p></article><article><span>Certification</span><h3>Google UX Design Certificate</h3><p>Coursera</p></article></div></div></section><section class="tool-section container"><p class="section-label">Tools & capabilities</p><div class="tool-list"><span>Figma</span><span>Adobe Creative Suite</span><span>Prototyping</span><span>Design systems</span><span>User research</span><span>Responsive design</span><span>Visual identity</span><span>Print production</span></div></section>{contact()}'''
write(Path('about/index.html'),shell('About','Meet Karthik Vempati, a UI/UX and graphic designer based in San Francisco with a background in applied arts and computer graphics.',about,'about'))

resume=f'''<section class="resume-page container"><div class="resume-title"><div><p class="section-label">Experience at a glance</p><h1>My <em>résumé.</em></h1></div><a class="button dark" href="/assets/Karthik_Vempati_Resume.docx" download>Download DOCX <span aria-hidden="true">↓</span></a></div><div class="resume-layout"><aside><h2>Karthik Vempati</h2><p>UI/UX & Graphic Designer</p><p>San Francisco, CA</p><a href="mailto:visualsbykarthik@gmail.com">visualsbykarthik@gmail.com</a><a href="https://www.linkedin.com/in/karthikvempati-design" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a><h3>Core strengths</h3><ul><li>User research & journey mapping</li><li>Wireframing & prototyping</li><li>Interaction & responsive design</li><li>Design systems & accessibility</li><li>Brand identity & print production</li></ul></aside><div><p class="large-copy">UI/UX Designer with 8+ years of experience combining user-centered digital design with visual communication across healthcare, web, e-commerce, and automotive work.</p><h2 class="resume-section-heading">Professional experience</h2>{experience_html}<h2 class="resume-section-heading">Education & certification</h2><div class="resume-education"><h3>MA in Computer Graphics</h3><p>Academy of Art University · February 2019–December 2021</p><h3>BFA in Applied Arts</h3><p>Osmania University · September 2010–December 2015</p><h3>Google UX Design Certificate</h3><p>Coursera</p></div><a class="text-link" href="/#collection">Explore selected projects {arrow()}</a></div></div></section>'''
write(Path('resume/index.html'),shell('Résumé','Experience, education, and capabilities of Karthik Vempati. Download the UI/UX and graphic design résumé.',resume,'resume'))
write(Path('404.html'),shell('Page not found','Find your way back to Karthik Vempati’s portfolio.','<section class="container not-found"><p class="section-label">404 / A small detour</p><h1>Let’s get you<br><em>back to the work.</em></h1><a class="button dark" href="/#collection">Explore projects →</a></section>'))
write(Path('favicon.svg'),'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#7e293b"/><text x="10" y="43" fill="#fff" font-family="Arial,sans-serif" font-size="34" font-weight="bold">kv</text></svg>')
print('Built home, six case studies, About, Résumé, and 404.')
